def get_klines(symbol, interval, startTime=None, endTime=None, timeZone=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "get_klines"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        return f"bmk_req_{uuid.uuid4().hex[:26]}"

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _cache_key(tool, params):
        h = hashlib.sha256((tool + "|" + _stable_json(params)).encode("utf-8")).hexdigest()
        return f"{tool}:{h}"

    def _find_working_active_key(api_keys_rows):
        active = [r for r in api_keys_rows if isinstance(r, dict) and r.get("status") == "active"]
        if not active:
            return None
        # Prefer highest limits to reduce false quota failures.
        def _score(k):
            try:
                return (int(k.get("daily_request_limit") or 0), int(k.get("rpm_limit") or 0))
            except Exception:
                return (0, 0)
        active.sort(key=_score, reverse=True)
        return active[0]

    def _get_or_create_counter(counters, api_key_id, bucket_type, bucket_start_dt, now_iso):
        bs_iso = _iso(bucket_start_dt)
        for r in counters:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                return r
        rid = f"bmk_use_{uuid.uuid4().hex[:26]}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "bucket_type": bucket_type,
            "bucket_start": bs_iso,
            "requests_total": 0,
            "requests_rejected": 0,
            "upstream_fetches": 0,
            "cache_hits": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    def _append_request(requests_rows, api_key_id, status, cache_key, cache_hit, symbol_id=None,
                        symbols_arr=None, interval=None, start_time_ms=None, end_time_ms=None,
                        time_zone=None, time_zone_offset_minutes=None, from_id=None, limit=None,
                        window_size=None, response_type=None, upstream_http_status=None,
                        error_code=None, error_message=None, latency_ms=None):
        now = _now_utc()
        now_iso = _iso(now)
        rid = f"bmk_req_{uuid.uuid4().hex[:26]}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "symbol_id": symbol_id,
            "symbols": symbols_arr,
            "interval": interval,
            "start_time_ms": start_time_ms,
            "end_time_ms": end_time_ms,
            "time_zone": time_zone,
            "time_zone_offset_minutes": time_zone_offset_minutes,
            "from_id": from_id,
            "limit": limit,
            "window_size": window_size,
            "response_type": response_type,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        requests_rows.append(row)
        return row

    def _coerce_int_ms(v, field):
        if v is None:
            return None
        if isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{field} must be a non-negative integer (milliseconds)")
        if isinstance(v, int):
            iv = v
        elif isinstance(v, float):
            if v != v:
                return _err("VALIDATION_ERROR", f"{field} must be a non-negative integer (milliseconds)")
            iv = int(v)
        else:
            return _err("VALIDATION_ERROR", f"{field} must be a non-negative integer (milliseconds)")
        if iv < 0:
            return _err("VALIDATION_ERROR", f"{field} must be >= 0")
        return iv

    api_keys = _load("api_keys.json")
    symbols_tbl = _load("symbols.json")
    requests_tbl = _load("requests.json")
    cache_tbl = _load("market_data_cache.json")
    counters_tbl = _load("usage_counters.json")

    api_key_row = _find_working_active_key(api_keys)
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request.")
    api_key_id = api_key_row.get("id")

    # Validate required inputs
    if not isinstance(symbol, str) or not symbol.strip():
        # rejected request (inactive symbol is separate); but we still log with best-effort cache_key
        params_norm = {"symbol": str(symbol).strip().upper() if isinstance(symbol, str) else None, "interval": interval, "startTime": startTime, "endTime": endTime, "timeZone": timeZone, "limit": limit}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="symbol must be a non-empty string")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if not isinstance(interval, str) or not interval.strip():
        params_norm = {"symbol": symbol.strip().upper(), "interval": interval}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="interval must be a non-empty string")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "interval must be a non-empty string")

    sym_norm = symbol.strip().upper()
    allowed_intervals = {"1m", "3m", "5m", "15m", "30m", "1h", "2h", "4h", "6h", "8h", "12h", "1d", "3d", "1w", "1M"}
    if interval not in allowed_intervals:
        params_norm = {"symbol": sym_norm, "interval": interval}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="interval is invalid")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "interval must be one of the supported values")

    # timeZone: tool schema says string, but audit shows numeric passed; accept any non-empty value and normalize to string.
    tz_norm = "UTC"
    if timeZone is not None:
        if isinstance(timeZone, str):
            if not timeZone.strip():
                # empty string invalid
                params_norm = {"symbol": sym_norm, "interval": interval}
                ck = _cache_key(tool_name, params_norm)
                _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="timeZone must be non-empty when provided")
                _save("requests.json", requests_tbl)
                return _err("VALIDATION_ERROR", "timeZone must be non-empty when provided")
            tz_norm = timeZone.strip()
        else:
            tz_norm = str(timeZone)

    st = _coerce_int_ms(startTime, "startTime")
    if isinstance(st, dict) and "error" in st:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message=st["error"]["message"])
        _save("requests.json", requests_tbl)
        return st
    et = _coerce_int_ms(endTime, "endTime")
    if isinstance(et, dict) and "error" in et:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message=et["error"]["message"])
        _save("requests.json", requests_tbl)
        return et
    if st is not None and et is not None and et < st:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="INVALID_TIME_RANGE", error_message="endTime must be >= startTime")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "endTime must be >= startTime")

    # limit (1..1000) default 500
    if limit is None:
        lim = 500
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)) or (isinstance(limit, float) and limit != limit):
            params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et}
            ck = _cache_key(tool_name, params_norm)
            _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="INVALID_LIMIT", error_message="limit must be between 1 and 1000")
            _save("requests.json", requests_tbl)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")
        lim = int(limit)
    if lim < 1 or lim > 1000:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et, "limit": lim}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="INVALID_LIMIT", error_message="limit must be between 1 and 1000")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    # Symbol existence + active
    sym_row = next((s for s in symbols_tbl if isinstance(s, dict) and s.get("symbol") == sym_norm), None)
    params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et, "limit": lim}
    ck = _cache_key(tool_name, params_norm)
    if sym_row is None or sym_row.get("status") != "active":
        _append_request(
            requests_tbl, api_key_id, "rejected", ck, False,
            symbol_id=sym_row.get("id") if isinstance(sym_row, dict) else None,
            interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
            error_code="UNKNOWN_SYMBOL", error_message="symbol is not active or not found"
        )
        _save("requests.json", requests_tbl)
        return _err("NOT_FOUND", "Unknown symbol", error_code="UNKNOWN_SYMBOL", symbol=sym_norm)

    # Quota enforcement (counts include accepted; rejected increments requests_rejected)
    now = _now_utc()
    now_iso = _iso(now)
    min_bucket = _bucket_start(now, "minute")
    day_bucket = _bucket_start(now, "day")
    min_row = _get_or_create_counter(counters_tbl, api_key_id, "minute", min_bucket, now_iso)
    day_row = _get_or_create_counter(counters_tbl, api_key_id, "day", day_bucket, now_iso)
    rpm_limit = int(api_key_row.get("rpm_limit") or 1)
    daily_limit = int(api_key_row.get("daily_request_limit") or 1)
    if int(min_row.get("requests_total") or 0) + 1 > rpm_limit or int(day_row.get("requests_total") or 0) + 1 > daily_limit:
        min_row["requests_rejected"] = int(min_row.get("requests_rejected") or 0) + 1
        day_row["requests_rejected"] = int(day_row.get("requests_rejected") or 0) + 1
        min_row["updated_at"] = now_iso
        day_row["updated_at"] = now_iso
        _append_request(
            requests_tbl, api_key_id, "rejected", ck, False,
            symbol_id=sym_row.get("id"), interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
            error_code="RATE_LIMITED", error_message="Quota exceeded for API key"
        )
        _save("usage_counters.json", counters_tbl)
        _save("requests.json", requests_tbl)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded", error_code="RATE_LIMITED")

    # Accept: increment totals
    min_row["requests_total"] = int(min_row.get("requests_total") or 0) + 1
    day_row["requests_total"] = int(day_row.get("requests_total") or 0) + 1
    min_row["updated_at"] = now_iso
    day_row["updated_at"] = now_iso

    # Cache lookup
    cache_entry = next((c for c in cache_tbl if isinstance(c, dict) and c.get("cache_key") == ck), None)

    def _parse_iso(v):
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    served_from_cache = False
    payload = None
    if cache_entry:
        exp = _parse_iso(cache_entry.get("expires_at"))
        status = cache_entry.get("status")
        if exp and exp > now and status in ("fresh", "stale"):
            served_from_cache = True
            payload = cache_entry.get("payload_json")

    if served_from_cache:
        min_row["cache_hits"] = int(min_row.get("cache_hits") or 0) + 1
        day_row["cache_hits"] = int(day_row.get("cache_hits") or 0) + 1
        latency_ms = int((time.time() - t0) * 1000)
        _append_request(
            requests_tbl, api_key_id, "served_from_cache", ck, True,
            symbol_id=sym_row.get("id"), interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
            latency_ms=latency_ms
        )
        _save("usage_counters.json", counters_tbl)
        _save("requests.json", requests_tbl)
        return {
            "symbol": sym_norm,
            "interval": interval,
            "startTime": st,
            "endTime": et,
            "timeZone": tz_norm,
            "limit": lim,
            "data": payload,
            "cache": {"hit": True, "cache_key": ck},
        }

    # Cache miss: simulate upstream fetch by returning existing cached payload if present (even if expired), otherwise deterministic empty list
    # and always upsert cache entry as fresh.
    min_row["upstream_fetches"] = int(min_row.get("upstream_fetches") or 0) + 1
    day_row["upstream_fetches"] = int(day_row.get("upstream_fetches") or 0) + 1

    upstream_payload = cache_entry.get("payload_json") if cache_entry and isinstance(cache_entry.get("payload_json"), (dict, list)) else []
    ttl_ms = int(api_key_row.get("default_cache_ttl_ms") or 0)
    if ttl_ms < 0:
        ttl_ms = 0
    fetched_at = now
    expires_at = now + datetime.timedelta(milliseconds=ttl_ms)
    fetched_iso = _iso(fetched_at)
    expires_iso = _iso(expires_at)
    payload_bytes = len(json.dumps(upstream_payload, ensure_ascii=False).encode("utf-8"))

    if cache_entry:
        cache_entry.update({
            "tool_name": tool_name,
            "primary_symbol_id": sym_row.get("id"),
            "symbols": None,
            "interval": interval,
            "start_time_ms": st,
            "end_time_ms": et,
            "time_zone": tz_norm,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": lim,
            "window_size": None,
            "response_type": None,
            "payload_json": upstream_payload,
            "payload_bytes": payload_bytes,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": fetched_iso,
            "expires_at": expires_iso,
            "updated_at": fetched_iso,
        })
    else:
        cache_tbl.append({
            "id": f"bmk_cch_{uuid.uuid4().hex[:26]}",
            "cache_key": ck,
            "tool_name": tool_name,
            "primary_symbol_id": sym_row.get("id"),
            "symbols": None,
            "interval": interval,
            "start_time_ms": st,
            "end_time_ms": et,
            "time_zone": tz_norm,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": lim,
            "window_size": None,
            "response_type": None,
            "payload_json": upstream_payload,
            "payload_bytes": payload_bytes,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": fetched_iso,
            "expires_at": expires_iso,
            "created_at": fetched_iso,
            "updated_at": fetched_iso,
        })

    latency_ms = int((time.time() - t0) * 1000)
    _append_request(
        requests_tbl, api_key_id, "fetched_upstream", ck, False,
        symbol_id=sym_row.get("id"), interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
        upstream_http_status=200, latency_ms=latency_ms
    )

    _save("usage_counters.json", counters_tbl)
    _save("market_data_cache.json", cache_tbl)
    _save("requests.json", requests_tbl)

    return {
        "symbol": sym_norm,
        "interval": interval,
        "startTime": st,
        "endTime": et,
        "timeZone": tz_norm,
        "limit": lim,
        "data": upstream_payload,
        "cache": {"hit": False, "cache_key": ck, "ttl_ms": ttl_ms},
    }

def get_ui_klines(symbol, interval, startTime=None, endTime=None, timeZone=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
