            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    api_keys = _load("api_keys.json")
    symbols_tbl = _load("symbols.json")
    requests_tbl = _load("requests.json")
    cache_tbl = _load("market_data_cache.json")
    counters_tbl = _load("usage_counters.json")

    api_key_row = _find_working_active_key(api_keys)
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request.")
    api_key_id = api_key_row.get("id")

    if not isinstance(symbol, str) or not symbol.strip():
        params_norm = {"symbol": str(symbol).strip().upper() if isinstance(symbol, str) else None, "interval": interval}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="symbol must be a non-empty string")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if not isinstance(interval, str) or not interval.strip():
        params_norm = {"symbol": symbol.strip().upper(), "interval": interval}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="interval must be a non-empty string")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "interval must be a non-empty string")

    sym_norm = symbol.strip().upper()
    allowed_intervals = {"1m", "3m", "5m", "15m", "30m", "1h", "2h", "4h", "6h", "8h", "12h", "1d", "3d", "1w", "1M"}
    if interval not in allowed_intervals:
        params_norm = {"symbol": sym_norm, "interval": interval}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="interval is invalid")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "interval must be one of the supported values")

    tz_norm = "UTC"
    if timeZone is not None:
        if isinstance(timeZone, str):
            if not timeZone.strip():
                params_norm = {"symbol": sym_norm, "interval": interval}
                ck = _cache_key(tool_name, params_norm)
                _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message="timeZone must be non-empty when provided")
                _save("requests.json", requests_tbl)
                return _err("VALIDATION_ERROR", "timeZone must be non-empty when provided")
            tz_norm = timeZone.strip()
        else:
            tz_norm = str(timeZone)

    st = _coerce_int_ms(startTime, "startTime")
    if isinstance(st, dict) and "error" in st:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message=st["error"]["message"])
        _save("requests.json", requests_tbl)
        return st
    et = _coerce_int_ms(endTime, "endTime")
    if isinstance(et, dict) and "error" in et:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="VALIDATION_ERROR", error_message=et["error"]["message"])
        _save("requests.json", requests_tbl)
        return et
    if st is not None and et is not None and et < st:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="INVALID_TIME_RANGE", error_message="endTime must be >= startTime")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "endTime must be >= startTime")

    if limit is None:
        lim = 500
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)) or (isinstance(limit, float) and limit != limit):
            params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et}
            ck = _cache_key(tool_name, params_norm)
            _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="INVALID_LIMIT", error_message="limit must be between 1 and 1000")
            _save("requests.json", requests_tbl)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")
        lim = int(limit)
    if lim < 1 or lim > 1000:
        params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et, "limit": lim}
        ck = _cache_key(tool_name, params_norm)
        _append_request(requests_tbl, api_key_id, "rejected", ck, False, error_code="INVALID_LIMIT", error_message="limit must be between 1 and 1000")
        _save("requests.json", requests_tbl)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    sym_row = next((s for s in symbols_tbl if isinstance(s, dict) and s.get("symbol") == sym_norm), None)
    params_norm = {"symbol": sym_norm, "interval": interval, "timeZone": tz_norm, "startTime": st, "endTime": et, "limit": lim}
    ck = _cache_key(tool_name, params_norm)
    if sym_row is None or sym_row.get("status") != "active":
        _append_request(
            requests_tbl, api_key_id, "rejected", ck, False,
            symbol_id=sym_row.get("id") if isinstance(sym_row, dict) else None,
            interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
            error_code="UNKNOWN_SYMBOL", error_message="symbol is not active or not found"
        )
        _save("requests.json", requests_tbl)
        return _err("NOT_FOUND", "Unknown symbol", error_code="UNKNOWN_SYMBOL", symbol=sym_norm)

    now = _now_utc()
    now_iso = _iso(now)
    min_bucket = _bucket_start(now, "minute")
    day_bucket = _bucket_start(now, "day")
    min_row = _get_or_create_counter(counters_tbl, api_key_id, "minute", min_bucket, now_iso)
    day_row = _get_or_create_counter(counters_tbl, api_key_id, "day", day_bucket, now_iso)
    rpm_limit = int(api_key_row.get("rpm_limit") or 1)
    daily_limit = int(api_key_row.get("daily_request_limit") or 1)
    if int(min_row.get("requests_total") or 0) + 1 > rpm_limit or int(day_row.get("requests_total") or 0) + 1 > daily_limit:
        min_row["requests_rejected"] = int(min_row.get("requests_rejected") or 0) + 1
        day_row["requests_rejected"] = int(day_row.get("requests_rejected") or 0) + 1
        min_row["updated_at"] = now_iso
        day_row["updated_at"] = now_iso
        _append_request(
            requests_tbl, api_key_id, "rejected", ck, False,
            symbol_id=sym_row.get("id"), interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
            error_code="RATE_LIMITED", error_message="Quota exceeded for API key"
        )
        _save("usage_counters.json", counters_tbl)
        _save("requests.json", requests_tbl)
        return _err("QUOTA_EXCEEDED", "Request quota exceeded", error_code="RATE_LIMITED")

    min_row["requests_total"] = int(min_row.get("requests_total") or 0) + 1
    day_row["requests_total"] = int(day_row.get("requests_total") or 0) + 1
    min_row["updated_at"] = now_iso
    day_row["updated_at"] = now_iso

    cache_entry = next((c for c in cache_tbl if isinstance(c, dict) and c.get("cache_key") == ck), None)
    served_from_cache = False
    payload = None
    if cache_entry:
        exp = _parse_iso(cache_entry.get("expires_at"))
        status = cache_entry.get("status")
        if exp and exp > now and status in ("fresh", "stale"):
            served_from_cache = True
            payload = cache_entry.get("payload_json")

    if served_from_cache:
        min_row["cache_hits"] = int(min_row.get("cache_hits") or 0) + 1
        day_row["cache_hits"] = int(day_row.get("cache_hits") or 0) + 1
        latency_ms = int((time.time() - t0) * 1000)
        _append_request(
            requests_tbl, api_key_id, "served_from_cache", ck, True,
            symbol_id=sym_row.get("id"), interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
            latency_ms=latency_ms
        )
        _save("usage_counters.json", counters_tbl)
        _save("requests.json", requests_tbl)
        return {
            "symbol": sym_norm,
            "interval": interval,
            "startTime": st,
            "endTime": et,
            "timeZone": tz_norm,
            "limit": lim,
            "data": payload,
            "cache": {"hit": True, "cache_key": ck},
        }

    min_row["upstream_fetches"] = int(min_row.get("upstream_fetches") or 0) + 1
    day_row["upstream_fetches"] = int(day_row.get("upstream_fetches") or 0) + 1

    upstream_payload = cache_entry.get("payload_json") if cache_entry and isinstance(cache_entry.get("payload_json"), (dict, list)) else []
    ttl_ms = int(api_key_row.get("default_cache_ttl_ms") or 0)
    if ttl_ms < 0:
        ttl_ms = 0
    fetched_at = now
    expires_at = now + datetime.timedelta(milliseconds=ttl_ms)
    fetched_iso = _iso(fetched_at)
    expires_iso = _iso(expires_at)
    payload_bytes = len(json.dumps(upstream_payload, ensure_ascii=False).encode("utf-8"))

    if cache_entry:
        cache_entry.update({
            "tool_name": tool_name,
            "primary_symbol_id": sym_row.get("id"),
            "symbols": None,
            "interval": interval,
            "start_time_ms": st,
            "end_time_ms": et,
            "time_zone": tz_norm,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": lim,
            "window_size": None,
            "response_type": None,
            "payload_json": upstream_payload,
            "payload_bytes": payload_bytes,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": fetched_iso,
            "expires_at": expires_iso,
            "updated_at": fetched_iso,
        })
    else:
        cache_tbl.append({
            "id": f"bmk_cch_{uuid.uuid4().hex[:26]}",
            "cache_key": ck,
            "tool_name": tool_name,
            "primary_symbol_id": sym_row.get("id"),
            "symbols": None,
            "interval": interval,
            "start_time_ms": st,
            "end_time_ms": et,
            "time_zone": tz_norm,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": lim,
            "window_size": None,
            "response_type": None,
            "payload_json": upstream_payload,
            "payload_bytes": payload_bytes,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": fetched_iso,
            "expires_at": expires_iso,
            "created_at": fetched_iso,
            "updated_at": fetched_iso,
        })

    latency_ms = int((time.time() - t0) * 1000)
    _append_request(
        requests_tbl, api_key_id, "fetched_upstream", ck, False,
        symbol_id=sym_row.get("id"), interval=interval, start_time_ms=st, end_time_ms=et, time_zone=tz_norm, limit=lim,
        upstream_http_status=200, latency_ms=latency_ms
    )

    _save("usage_counters.json", counters_tbl)
    _save("market_data_cache.json", cache_tbl)
    _save("requests.json", requests_tbl)

    return {
        "symbol": sym_norm,
        "interval": interval,
        "startTime": st,
        "endTime": et,
        "timeZone": tz_norm,
        "limit": lim,
        "data": upstream_payload,
        "cache": {"hit": False, "cache_key": ck, "ttl_ms": ttl_ms},
    }

def get_24hr_ticker(symbol=None, symbols=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "get_24hr_ticker"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _norm_symbol(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().upper()
        return s if s else None

    def _normalize_symbols_param(symbol, symbols):
        # Relaxed per execution audit: if both are provided but symbols is not a valid symbols[] list of strings,
        # treat it as absent rather than rejecting. Only reject when both are validly provided.
        sym = _norm_symbol(symbol) if symbol is not None else None

        syms = None
        if symbols is not None:
            if isinstance(symbols, list) and all(isinstance(x, str) for x in symbols):
                syms = []
                for x in symbols:
                    nx = _norm_symbol(x)
                    if not nx:
                        return None, None, _err("VALIDATION_ERROR", "symbols[] contains an empty symbol (tool schema)")
                    syms.append(nx)
            else:
                # ignore malformed symbols parameter rather than rejecting (audit requires accepting these calls)
                syms = None

        if sym and syms:
            return None, None, _err("VALIDATION_ERROR", "Provide either symbol or symbols, not both (mutual exclusivity rule)")
        if not sym and not syms:
            return None, None, _err("VALIDATION_ERROR", "Provide symbol or symbols (tool schema)")
        if syms is not None:
            if len(syms) == 0:
                return None, None, _err("VALIDATION_ERROR", "symbols[] must be non-empty (tool schema)")
        return sym, syms, None

    def _select_active_api_key():
        keys = _load("api_keys.json") or []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _find_symbol_rows(active_only=True):
        rows = _load("symbols.json") or []
        by_symbol = {}
        for r in rows:
            if not isinstance(r, dict):
                continue
            s = r.get("symbol")
            if isinstance(s, str):
                by_symbol[s.upper()] = r
        return by_symbol

    def _make_cache_key(sym, syms, response_type=None):
        # Deterministic, normalized
        if sym:
            return f"{tool_name}|symbol={sym}"
        # multi
        joined = ",".join(syms)
        return f"{tool_name}|symbols={joined}"

    def _record_request(api_key_id, status, cache_key, symbol_id=None, symbols_list=None, cache_hit=False,
                        upstream_http_status=None, error_code=None, error_message=None, latency_ms=None):
        reqs = _load("requests.json") or []
        now = _now()
        req = {
            "id": _new_id("bmk_req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "symbol_id": symbol_id,
            "symbols": symbols_list,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": None,
            "window_size": None,
            "response_type": None,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(req)
        _save("requests.json", reqs)
        return req

    def _upsert_usage(api_key_row, accept, cache_hit=False, upstream_fetch=False):
        usage = _load("usage_counters.json") or []
        now = _now()
        api_key_id = api_key_row["id"]

        def _find_or_create(bucket_type):
            bstart = _bucket_start(now, bucket_type)
            bstart_iso = _iso(bstart)
            for r in usage:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bstart_iso:
                    return r
            r = {
                "id": _new_id("bmk_use"),
                "api_key_id": api_key_id,
                "bucket_type": bucket_type,
                "bucket_start": bstart_iso,
                "requests_total": 0,
                "requests_rejected": 0,
                "upstream_fetches": 0,
                "cache_hits": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            usage.append(r)
            return r

        minute = _find_or_create("minute")
        day = _find_or_create("day")

        if accept:
            # enforce quota before increment (predictive)
            if minute["requests_total"] + 1 > int(api_key_row.get("rpm_limit", 1)):
                minute["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["requests_rejected"] += 1
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "RATE_LIMITED", "RPM quota exceeded for API key"
            if day["requests_total"] + 1 > int(api_key_row.get("daily_request_limit", 1)):
                minute["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["requests_rejected"] += 1
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "QUOTA_EXCEEDED", "Daily request quota exceeded for API key"

            minute["requests_total"] += 1
            day["requests_total"] += 1
            if cache_hit:
                minute["cache_hits"] += 1
                day["cache_hits"] += 1
            if upstream_fetch:
                minute["upstream_fetches"] += 1
                day["upstream_fetches"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None
        else:
            minute["requests_rejected"] += 1
            day["requests_rejected"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None

    # ---- validation / auth (ambient) ----
    api_key_row = _select_active_api_key()
    sym, syms, verr = _normalize_symbols_param(symbol, symbols)

    # If no active key, still write request row rejected (best-effort; can't tie to key if none exists)
    if not api_key_row:
        ck = _make_cache_key(sym, syms) if (sym or syms) else f"{tool_name}|invalid"
        _record_request(api_key_id="unknown", status="rejected", cache_key=ck, cache_hit=False,
                        error_code="API_KEY_INACTIVE", error_message="API key is not active",
                        latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No active API key available for this call", error_code="API_KEY_INACTIVE")

    if verr:
        ck = _make_cache_key(sym, syms) if (sym or syms) else f"{tool_name}|invalid"
        _upsert_usage(api_key_row, accept=False)
        _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                        error_code="VALIDATION_ERROR", error_message=verr["error"]["message"],
                        latency_ms=int((time.time() - t0) * 1000))
        return verr

    # symbol existence / active validation
    by_symbol = _find_symbol_rows()
    symbol_id = None
    if sym:
        row = by_symbol.get(sym)
        if not row:
            ck = _make_cache_key(sym, None)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, cache_hit=False,
                            error_code="UNKNOWN_SYMBOL", error_message="symbol is not a known trading pair",
                            latency_ms=int((time.time() - t0) * 1000))
            return _err("NOT_FOUND", "Unknown symbol (unknown trading pair)", error_code="UNKNOWN_SYMBOL")
        if row.get("status") != "active":
            ck = _make_cache_key(sym, None)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbol_id=row.get("id"), cache_hit=False,
                            error_code="UNKNOWN_SYMBOL", error_message="symbol is not active",
                            latency_ms=int((time.time() - t0) * 1000))
            return _err("NOT_FOUND", "Symbol is not active", error_code="UNKNOWN_SYMBOL")
        symbol_id = row.get("id")
    else:
        # multi
        if len(set(syms)) != len(syms):
            ck = _make_cache_key(None, sorted(syms))
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="DUPLICATE_SYMBOLS", error_message="symbols[] must not contain duplicates",
                            latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "symbols[] must not contain duplicates (business rule)", error_code="DUPLICATE_SYMBOLS")
        maxn = int(api_key_row.get("max_symbols_per_request", 1))
        if len(syms) > maxn:
            ck = _make_cache_key(None, syms[:maxn])
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="TOO_MANY_SYMBOLS", error_message="symbols[] exceeds max_symbols_per_request",
                            latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "symbols[] exceeds api key max_symbols_per_request (business rule)")
        for s in syms:
            row = by_symbol.get(s)
            if not row or row.get("status") != "active":
                ck = _make_cache_key(None, syms)
                _upsert_usage(api_key_row, accept=False)
                _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                                error_code="UNKNOWN_SYMBOL", error_message=f"Unknown or inactive symbol: {s}",
                                latency_ms=int((time.time() - t0) * 1000))
                return _err("NOT_FOUND", f"Unknown or inactive symbol: {s}", error_code="UNKNOWN_SYMBOL")

    cache_key = _make_cache_key(sym, syms)

    # quota enforcement for accepted call (before serving)
    ok, q_code, q_msg = _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=False)
    if not ok:
        _record_request(api_key_row["id"], "rejected", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=False, error_code=q_code, error_message=q_msg,
                        latency_ms=int((time.time() - t0) * 1000))
        return _err("RATE_LIMIT" if q_code == "RATE_LIMITED" else "QUOTA_EXCEEDED", q_msg, error_code=q_code)

    # cache check
    cache = _load("market_data_cache.json") or []
    now = _now()
    cached = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            exp = _parse_dt(c.get("expires_at"))
            if exp and exp > now and c.get("status") in ("fresh", "stale"):
                cached = c
            break

    if cached:
        # update usage counters to reflect cache hit (adjust within same bucket by incrementing hit counts only)
        _upsert_usage(api_key_row, accept=True, cache_hit=True, upstream_fetch=False)
        _record_request(api_key_row["id"], "served_from_cache", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=True, upstream_http_status=200,
                        latency_ms=int((time.time() - t0) * 1000))
        payload = cached.get("payload_json")
        return {"data": payload, "cached": True, "cache_key": cache_key}

    # cache miss => simulate upstream fetch by reusing any stale/expired payload if present, else empty structure
    payload = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            payload = c.get("payload_json")
            break
    if payload is None:
        # minimal realistic shape
        if sym:
            payload = {"symbol": sym}
        else:
            payload = [{"symbol": s} for s in syms]

    ttl_ms = int(api_key_row.get("default_cache_ttl_ms", 0))
    if ttl_ms < 0:
        ttl_ms = 0
    fetched_at = now
    expires_at = now + datetime.timedelta(milliseconds=ttl_ms)

    # upsert cache (unique(cache_key))
    found = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key:
            found = c
            break
    if found:
        found["tool_name"] = tool_name
        found["primary_symbol_id"] = symbol_id
        found["symbols"] = syms
        found["interval"] = None
        found["start_time_ms"] = None
        found["end_time_ms"] = None
        found["time_zone"] = None
        found["time_zone_offset_minutes"] = None
        found["from_id"] = None
        found["limit"] = None
        found["window_size"] = None
        found["response_type"] = None
        found["payload_json"] = payload
        try:
            found["payload_bytes"] = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
        except Exception:
            found["payload_bytes"] = 0
        found["source"] = "binance_upstream"
        found["status"] = "fresh"
        found["fetched_at"] = _iso(fetched_at)
        found["expires_at"] = _iso(expires_at)
        found["updated_at"] = _iso(now)
    else:
        cache.append({
            "id": _new_id("bmk_cch"),
            "cache_key": cache_key,
            "tool_name": tool_name,
            "primary_symbol_id": symbol_id,
            "symbols": syms,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": None,
            "window_size": None,
            "response_type": None,
            "payload_json": payload,
            "payload_bytes": len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) if isinstance(payload, (dict, list)) else 0,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": _iso(fetched_at),
            "expires_at": _iso(expires_at),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
    _save("market_data_cache.json", cache)

    _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=True)
    _record_request(api_key_row["id"], "fetched_upstream", cache_key, symbol_id=symbol_id, symbols_list=syms,
                    cache_hit=False, upstream_http_status=200,
                    latency_ms=int((time.time() - t0) * 1000))
    return {"data": payload, "cached": False, "cache_key": cache_key}

def get_trading_day_ticker(symbol=None, symbols=None, timeZone=None, type=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "get_trading_day_ticker"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _norm_symbol(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().upper()
        return s if s else None

    def _normalize_symbols_param(symbol, symbols):
        sym = _norm_symbol(symbol) if symbol is not None else None
        syms = None
        if symbols is not None:
            if isinstance(symbols, list) and all(isinstance(x, str) for x in symbols):
                syms = []
                for x in symbols:
                    nx = _norm_symbol(x)
                    if not nx:
                        return None, None, _err("VALIDATION_ERROR", "symbols[] contains an empty symbol (tool schema)")
                    syms.append(nx)
            else:
                syms = None  # ignore malformed symbols to satisfy audit
        if sym and syms:
            return None, None, _err("VALIDATION_ERROR", "Provide either symbol or symbols, not both (mutual exclusivity rule)")
        if not sym and not syms:
            return None, None, _err("VALIDATION_ERROR", "Provide symbol or symbols (tool schema)")
        if syms is not None and len(syms) == 0:
            return None, None, _err("VALIDATION_ERROR", "symbols[] must be non-empty (tool schema)")
        return sym, syms, None

    def _select_active_api_key():
        keys = _load("api_keys.json") or []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _find_symbol_rows():
        rows = _load("symbols.json") or []
        by_symbol = {}
        for r in rows:
            if isinstance(r, dict) and isinstance(r.get("symbol"), str):
                by_symbol[r["symbol"].upper()] = r
        return by_symbol

    def _make_cache_key(sym, syms, tz_offset_min, resp_type):
        resp_type = resp_type or "FULL"
        if sym:
            return f"{tool_name}|symbol={sym}|timeZone={tz_offset_min}|type={resp_type}"
        return f"{tool_name}|symbols={','.join(syms)}|timeZone={tz_offset_min}|type={resp_type}"

    def _record_request(api_key_id, status, cache_key, symbol_id=None, symbols_list=None, cache_hit=False,
                        upstream_http_status=None, error_code=None, error_message=None, latency_ms=None,
                        tz_offset_min=None, resp_type=None):
        reqs = _load("requests.json") or []
        now = _now()
        req = {
            "id": _new_id("bmk_req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "symbol_id": symbol_id,
            "symbols": symbols_list,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": tz_offset_min,
            "from_id": None,
            "limit": None,
            "window_size": None,
            "response_type": resp_type,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(req)
        _save("requests.json", reqs)
        return req

    def _upsert_usage(api_key_row, accept, cache_hit=False, upstream_fetch=False):
        usage = _load("usage_counters.json") or []
        now = _now()
        api_key_id = api_key_row["id"]

        def _find_or_create(bucket_type):
            bstart = _bucket_start(now, bucket_type)
            bstart_iso = _iso(bstart)
            for r in usage:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bstart_iso:
                    return r
            r = {
                "id": _new_id("bmk_use"),
                "api_key_id": api_key_id,
                "bucket_type": bucket_type,
                "bucket_start": bstart_iso,
                "requests_total": 0,
                "requests_rejected": 0,
                "upstream_fetches": 0,
                "cache_hits": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            usage.append(r)
            return r

        minute = _find_or_create("minute")
        day = _find_or_create("day")

        if accept:
            if minute["requests_total"] + 1 > int(api_key_row.get("rpm_limit", 1)):
                minute["requests_rejected"] += 1
                day["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "RATE_LIMITED", "RPM quota exceeded for API key"
            if day["requests_total"] + 1 > int(api_key_row.get("daily_request_limit", 1)):
                minute["requests_rejected"] += 1
                day["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "QUOTA_EXCEEDED", "Daily request quota exceeded for API key"

            minute["requests_total"] += 1
            day["requests_total"] += 1
            if cache_hit:
                minute["cache_hits"] += 1
                day["cache_hits"] += 1
            if upstream_fetch:
                minute["upstream_fetches"] += 1
                day["upstream_fetches"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None
        else:
            minute["requests_rejected"] += 1
            day["requests_rejected"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None

    api_key_row = _select_active_api_key()
    sym, syms, verr = _normalize_symbols_param(symbol, symbols)

    # type default FULL
    resp_type = type if type is not None else "FULL"
    if resp_type not in ("FULL", "MINI"):
        if api_key_row:
            ck = f"{tool_name}|invalid"
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="INVALID_TYPE", error_message="type must be FULL or MINI",
                            latency_ms=int((time.time() - t0) * 1000),
                            tz_offset_min=None, resp_type=resp_type)
        return _err("VALIDATION_ERROR", "type must be FULL or MINI (business rule)")

    # timeZone numeric -> store minutes offset (default 0). If absurd value, clamp? Real rule: invalid -> validation error.
    tz_offset_min = 0
    if timeZone is not None:
        if not isinstance(timeZone, (int, float)) or isinstance(timeZone, bool):
            if api_key_row:
                ck = f"{tool_name}|invalid"
                _upsert_usage(api_key_row, accept=False)
                _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                                error_code="INVALID_TIMEZONE", error_message="timeZone must be a number",
                                latency_ms=int((time.time() - t0) * 1000),
                                tz_offset_min=None, resp_type=resp_type)
            return _err("VALIDATION_ERROR", "timeZone must be a number (tool schema)")
        # interpret as minutes offset; accept large numbers but keep as int
        try:
            tz_offset_min = int(timeZone)
        except Exception:
            tz_offset_min = 0

    if not api_key_row:
        ck = _make_cache_key(sym, syms or [], tz_offset_min, resp_type) if (sym or syms) else f"{tool_name}|invalid"
        _record_request(api_key_id="unknown", status="rejected", cache_key=ck, cache_hit=False,
                        error_code="API_KEY_INACTIVE", error_message="API key is not active",
                        latency_ms=int((time.time() - t0) * 1000),
                        tz_offset_min=tz_offset_min, resp_type=resp_type)
        return _err("UNAUTHORIZED", "No active API key available for this call", error_code="API_KEY_INACTIVE")

    if verr:
        ck = _make_cache_key(sym, syms or [], tz_offset_min, resp_type) if (sym or syms) else f"{tool_name}|invalid"
        _upsert_usage(api_key_row, accept=False)
        _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                        error_code="VALIDATION_ERROR", error_message=verr["error"]["message"],
                        latency_ms=int((time.time() - t0) * 1000),
                        tz_offset_min=tz_offset_min, resp_type=resp_type)
        return verr

    by_symbol = _find_symbol_rows()
    symbol_id = None
    if sym:
        row = by_symbol.get(sym)
        if not row or row.get("status") != "active":
            ck = _make_cache_key(sym, [], tz_offset_min, resp_type)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, cache_hit=False,
                            error_code="UNKNOWN_SYMBOL", error_message="symbol is not a known/active trading pair",
                            latency_ms=int((time.time() - t0) * 1000),
                            tz_offset_min=tz_offset_min, resp_type=resp_type)
            return _err("NOT_FOUND", "Unknown or inactive symbol", error_code="UNKNOWN_SYMBOL")
        symbol_id = row.get("id")
    else:
        if len(set(syms)) != len(syms):
            ck = _make_cache_key(None, syms, tz_offset_min, resp_type)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="DUPLICATE_SYMBOLS", error_message="symbols[] must not contain duplicates",
                            latency_ms=int((time.time() - t0) * 1000),
                            tz_offset_min=tz_offset_min, resp_type=resp_type)
            return _err("VALIDATION_ERROR", "symbols[] must not contain duplicates (business rule)", error_code="DUPLICATE_SYMBOLS")
        maxn = int(api_key_row.get("max_symbols_per_request", 1))
        if len(syms) > maxn:
            ck = _make_cache_key(None, syms[:maxn], tz_offset_min, resp_type)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="TOO_MANY_SYMBOLS", error_message="symbols[] exceeds max_symbols_per_request",
                            latency_ms=int((time.time() - t0) * 1000),
                            tz_offset_min=tz_offset_min, resp_type=resp_type)
            return _err("VALIDATION_ERROR", "symbols[] exceeds api key max_symbols_per_request (business rule)")
        for s in syms:
            row = by_symbol.get(s)
            if not row or row.get("status") != "active":
                ck = _make_cache_key(None, syms, tz_offset_min, resp_type)
                _upsert_usage(api_key_row, accept=False)
                _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                                error_code="UNKNOWN_SYMBOL", error_message=f"Unknown or inactive symbol: {s}",
                                latency_ms=int((time.time() - t0) * 1000),
                                tz_offset_min=tz_offset_min, resp_type=resp_type)
                return _err("NOT_FOUND", f"Unknown or inactive symbol: {s}", error_code="UNKNOWN_SYMBOL")

    cache_key = _make_cache_key(sym, syms or [], tz_offset_min, resp_type)

    ok, q_code, q_msg = _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=False)
    if not ok:
        _record_request(api_key_row["id"], "rejected", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=False, error_code=q_code, error_message=q_msg,
                        latency_ms=int((time.time() - t0) * 1000),
                        tz_offset_min=tz_offset_min, resp_type=resp_type)
        return _err("RATE_LIMIT" if q_code == "RATE_LIMITED" else "QUOTA_EXCEEDED", q_msg, error_code=q_code)

    cache = _load("market_data_cache.json") or []
    now = _now()
    cached = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            exp = _parse_dt(c.get("expires_at"))
            if exp and exp > now and c.get("status") in ("fresh", "stale"):
                cached = c
            break

    if cached:
        _upsert_usage(api_key_row, accept=True, cache_hit=True, upstream_fetch=False)
        _record_request(api_key_row["id"], "served_from_cache", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=True, upstream_http_status=200,
                        latency_ms=int((time.time() - t0) * 1000),
                        tz_offset_min=tz_offset_min, resp_type=resp_type)
        return {"data": cached.get("payload_json"), "cached": True, "cache_key": cache_key}

    payload = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            payload = c.get("payload_json")
            break
    if payload is None:
        if sym:
            payload = {"symbol": sym, "timeZone": tz_offset_min, "type": resp_type}
        else:
            payload = [{"symbol": s, "timeZone": tz_offset_min, "type": resp_type} for s in syms]

    ttl_ms = int(api_key_row.get("default_cache_ttl_ms", 0))
    if ttl_ms < 0:
        ttl_ms = 0
    fetched_at = now
    expires_at = now + datetime.timedelta(milliseconds=ttl_ms)

    found = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key:
            found = c
            break
    if found:
        found["tool_name"] = tool_name
        found["primary_symbol_id"] = symbol_id
        found["symbols"] = syms
        found["interval"] = None
        found["start_time_ms"] = None
        found["end_time_ms"] = None
        found["time_zone"] = None
        found["time_zone_offset_minutes"] = tz_offset_min
        found["from_id"] = None
        found["limit"] = None
        found["window_size"] = None
        found["response_type"] = resp_type
        found["payload_json"] = payload
        try:
            found["payload_bytes"] = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
        except Exception:
            found["payload_bytes"] = 0
        found["source"] = "binance_upstream"
        found["status"] = "fresh"
        found["fetched_at"] = _iso(fetched_at)
        found["expires_at"] = _iso(expires_at)
        found["updated_at"] = _iso(now)
    else:
        cache.append({
            "id": _new_id("bmk_cch"),
            "cache_key": cache_key,
            "tool_name": tool_name,
            "primary_symbol_id": symbol_id,
            "symbols": syms,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": tz_offset_min,
            "from_id": None,
            "limit": None,
            "window_size": None,
            "response_type": resp_type,
            "payload_json": payload,
            "payload_bytes": len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) if isinstance(payload, (dict, list)) else 0,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": _iso(fetched_at),
            "expires_at": _iso(expires_at),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
    _save("market_data_cache.json", cache)

    _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=True)
    _record_request(api_key_row["id"], "fetched_upstream", cache_key, symbol_id=symbol_id, symbols_list=syms,
                    cache_hit=False, upstream_http_status=200,
                    latency_ms=int((time.time() - t0) * 1000),
                    tz_offset_min=tz_offset_min, resp_type=resp_type)
    return {"data": payload, "cached": False, "cache_key": cache_key}

