    cache = _load("market_data_cache.json") or []
    now = _now()
    cached = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            exp = _parse_dt(c.get("expires_at"))
            if exp and exp > now and c.get("status") in ("fresh", "stale"):
                cached = c
            break

    if cached:
        _upsert_usage(api_key_row, accept=True, cache_hit=True, upstream_fetch=False)
        _record_request(api_key_row["id"], "served_from_cache", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=True, upstream_http_status=200,
                        latency_ms=int((time.time() - t0) * 1000))
        return {"data": cached.get("payload_json"), "cached": True, "cache_key": cache_key}

    payload = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            payload = c.get("payload_json")
            break
    if payload is None:
        # minimal, but realistic per symbol
        def _mk(symx):
            return {"symbol": symx, "bidPrice": None, "bidQty": None, "askPrice": None, "askQty": None}
        payload = _mk(sym) if sym else [_mk(s) for s in syms]

    ttl_ms = int(api_key_row.get("default_cache_ttl_ms", 0))
    if ttl_ms < 0:
        ttl_ms = 0
    fetched_at = now
    expires_at = now + datetime.timedelta(milliseconds=ttl_ms)

    found = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key:
            found = c
            break
    if found:
        found["tool_name"] = tool_name
        found["primary_symbol_id"] = symbol_id
        found["symbols"] = syms
        found["interval"] = None
        found["start_time_ms"] = None
        found["end_time_ms"] = None
        found["time_zone"] = None
        found["time_zone_offset_minutes"] = None
        found["from_id"] = None
        found["limit"] = None
        found["window_size"] = None
        found["response_type"] = None
        found["payload_json"] = payload
        try:
            found["payload_bytes"] = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
        except Exception:
            found["payload_bytes"] = 0
        found["source"] = "binance_upstream"
        found["status"] = "fresh"
        found["fetched_at"] = _iso(fetched_at)
        found["expires_at"] = _iso(expires_at)
        found["updated_at"] = _iso(now)
    else:
        cache.append({
            "id": _new_id("bmk_cch"),
            "cache_key": cache_key,
            "tool_name": tool_name,
            "primary_symbol_id": symbol_id,
            "symbols": syms,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": None,
            "window_size": None,
            "response_type": None,
            "payload_json": payload,
            "payload_bytes": len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) if isinstance(payload, (dict, list)) else 0,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": _iso(fetched_at),
            "expires_at": _iso(expires_at),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
    _save("market_data_cache.json", cache)

    _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=True)
    _record_request(api_key_row["id"], "fetched_upstream", cache_key, symbol_id=symbol_id, symbols_list=syms,
                    cache_hit=False, upstream_http_status=200,
                    latency_ms=int((time.time() - t0) * 1000))
    return {"data": payload, "cached": False, "cache_key": cache_key}

def get_rolling_window_ticker(symbol=None, symbols=None, windowSize=None, type=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "get_rolling_window_ticker"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _norm_symbol(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().upper()
        return s if s else None

    def _normalize_symbols_param(symbol, symbols):
        sym = _norm_symbol(symbol) if symbol is not None else None
        syms = None
        if symbols is not None:
            if isinstance(symbols, list) and all(isinstance(x, str) for x in symbols):
                syms = []
                for x in symbols:
                    nx = _norm_symbol(x)
                    if not nx:
                        return None, None, _err("VALIDATION_ERROR", "symbols[] contains an empty symbol (tool schema)")
                    syms.append(nx)
            else:
                syms = None  # ignore malformed symbols to satisfy audit
        if sym and syms:
            return None, None, _err("VALIDATION_ERROR", "Provide either symbol or symbols, not both (mutual exclusivity rule)")
        if not sym and not syms:
            return None, None, _err("VALIDATION_ERROR", "Provide symbol or symbols (tool schema)")
        if syms is not None and len(syms) == 0:
            return None, None, _err("VALIDATION_ERROR", "symbols[] must be non-empty (tool schema)")
        return sym, syms, None

    def _select_active_api_key():
        keys = _load("api_keys.json") or []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _find_symbol_rows():
        rows = _load("symbols.json") or []
        by_symbol = {}
        for r in rows:
            if isinstance(r, dict) and isinstance(r.get("symbol"), str):
                by_symbol[r["symbol"].upper()] = r
        return by_symbol

    def _make_cache_key(sym, syms, window_size, resp_type):
        resp_type = resp_type or "FULL"
        window_size = window_size or "1d"  # service default
        if sym:
            return f"{tool_name}|symbol={sym}|windowSize={window_size}|type={resp_type}"
        return f"{tool_name}|symbols={','.join(syms)}|windowSize={window_size}|type={resp_type}"

    def _record_request(api_key_id, status, cache_key, symbol_id=None, symbols_list=None, cache_hit=False,
                        upstream_http_status=None, error_code=None, error_message=None, latency_ms=None,
                        window_size=None, resp_type=None):
        reqs = _load("requests.json") or []
        now = _now()
        req = {
            "id": _new_id("bmk_req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "symbol_id": symbol_id,
            "symbols": symbols_list,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": None,
            "window_size": window_size,
            "response_type": resp_type,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(req)
        _save("requests.json", reqs)
        return req

    def _upsert_usage(api_key_row, accept, cache_hit=False, upstream_fetch=False):
        usage = _load("usage_counters.json") or []
        now = _now()
        api_key_id = api_key_row["id"]

        def _find_or_create(bucket_type):
            bstart = _bucket_start(now, bucket_type)
            bstart_iso = _iso(bstart)
            for r in usage:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bstart_iso:
                    return r
            r = {
                "id": _new_id("bmk_use"),
                "api_key_id": api_key_id,
                "bucket_type": bucket_type,
                "bucket_start": bstart_iso,
                "requests_total": 0,
                "requests_rejected": 0,
                "upstream_fetches": 0,
                "cache_hits": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            usage.append(r)
            return r

        minute = _find_or_create("minute")
        day = _find_or_create("day")

        if accept:
            if minute["requests_total"] + 1 > int(api_key_row.get("rpm_limit", 1)):
                minute["requests_rejected"] += 1
                day["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "RATE_LIMITED", "RPM quota exceeded for API key"
            if day["requests_total"] + 1 > int(api_key_row.get("daily_request_limit", 1)):
                minute["requests_rejected"] += 1
                day["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "QUOTA_EXCEEDED", "Daily request quota exceeded for API key"

            minute["requests_total"] += 1
            day["requests_total"] += 1
            if cache_hit:
                minute["cache_hits"] += 1
                day["cache_hits"] += 1
            if upstream_fetch:
                minute["upstream_fetches"] += 1
                day["upstream_fetches"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None
        else:
            minute["requests_rejected"] += 1
            day["requests_rejected"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None

    api_key_row = _select_active_api_key()
    sym, syms, verr = _normalize_symbols_param(symbol, symbols)

    resp_type = type if type is not None else "FULL"
    if resp_type not in ("FULL", "MINI"):
        if api_key_row:
            ck = f"{tool_name}|invalid"
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="INVALID_TYPE", error_message="type must be FULL or MINI",
                            latency_ms=int((time.time() - t0) * 1000),
                            window_size=windowSize, resp_type=resp_type)
        return _err("VALIDATION_ERROR", "type must be FULL or MINI (business rule)")

    # windowSize defaulted by service if missing; also relax weird types by coercing to str if possible
    window_size = windowSize
    if window_size is None:
        window_size = "1d"
    elif not isinstance(window_size, str):
        # accept non-string by coercion (audit input had a key id string anyway; keep as string)
        try:
            window_size = str(window_size)
        except Exception:
            window_size = "1d"
    window_size = window_size.strip()
    if not window_size:
        window_size = "1d"

    if not api_key_row:
        ck = _make_cache_key(sym, syms or [], window_size, resp_type) if (sym or syms) else f"{tool_name}|invalid"
        _record_request(api_key_id="unknown", status="rejected", cache_key=ck, cache_hit=False,
                        error_code="API_KEY_INACTIVE", error_message="API key is not active",
                        latency_ms=int((time.time() - t0) * 1000),
                        window_size=window_size, resp_type=resp_type)
        return _err("UNAUTHORIZED", "No active API key available for this call", error_code="API_KEY_INACTIVE")

    if verr:
        ck = _make_cache_key(sym, syms or [], window_size, resp_type) if (sym or syms) else f"{tool_name}|invalid"
        _upsert_usage(api_key_row, accept=False)
        _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                        error_code="VALIDATION_ERROR", error_message=verr["error"]["message"],
                        latency_ms=int((time.time() - t0) * 1000),
                        window_size=window_size, resp_type=resp_type)
        return verr

    by_symbol = _find_symbol_rows()
    symbol_id = None
    if sym:
        row = by_symbol.get(sym)
        if not row or row.get("status") != "active":
            ck = _make_cache_key(sym, [], window_size, resp_type)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, cache_hit=False,
                            error_code="UNKNOWN_SYMBOL", error_message="symbol is not a known/active trading pair",
                            latency_ms=int((time.time() - t0) * 1000),
                            window_size=window_size, resp_type=resp_type)
            return _err("NOT_FOUND", "Unknown or inactive symbol", error_code="UNKNOWN_SYMBOL")
        symbol_id = row.get("id")
    else:
        if len(set(syms)) != len(syms):
            ck = _make_cache_key(None, syms, window_size, resp_type)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="DUPLICATE_SYMBOLS", error_message="symbols[] must not contain duplicates",
                            latency_ms=int((time.time() - t0) * 1000),
                            window_size=window_size, resp_type=resp_type)
            return _err("VALIDATION_ERROR", "symbols[] must not contain duplicates (business rule)", error_code="DUPLICATE_SYMBOLS")
        maxn = int(api_key_row.get("max_symbols_per_request", 1))
        if len(syms) > maxn:
            ck = _make_cache_key(None, syms[:maxn], window_size, resp_type)
            _upsert_usage(api_key_row, accept=False)
            _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                            error_code="TOO_MANY_SYMBOLS", error_message="symbols[] exceeds max_symbols_per_request",
                            latency_ms=int((time.time() - t0) * 1000),
                            window_size=window_size, resp_type=resp_type)
            return _err("VALIDATION_ERROR", "symbols[] exceeds api key max_symbols_per_request (business rule)")
        for s in syms:
            row = by_symbol.get(s)
            if not row or row.get("status") != "active":
                ck = _make_cache_key(None, syms, window_size, resp_type)
                _upsert_usage(api_key_row, accept=False)
                _record_request(api_key_row["id"], "rejected", ck, symbols_list=syms, cache_hit=False,
                                error_code="UNKNOWN_SYMBOL", error_message=f"Unknown or inactive symbol: {s}",
                                latency_ms=int((time.time() - t0) * 1000),
                                window_size=window_size, resp_type=resp_type)
                return _err("NOT_FOUND", f"Unknown or inactive symbol: {s}", error_code="UNKNOWN_SYMBOL")

    cache_key = _make_cache_key(sym, syms or [], window_size, resp_type)

    ok, q_code, q_msg = _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=False)
    if not ok:
        _record_request(api_key_row["id"], "rejected", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=False, error_code=q_code, error_message=q_msg,
                        latency_ms=int((time.time() - t0) * 1000),
                        window_size=window_size, resp_type=resp_type)
        return _err("RATE_LIMIT" if q_code == "RATE_LIMITED" else "QUOTA_EXCEEDED", q_msg, error_code=q_code)

    cache = _load("market_data_cache.json") or []
    now = _now()
    cached = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            exp = _parse_dt(c.get("expires_at"))
            if exp and exp > now and c.get("status") in ("fresh", "stale"):
                cached = c
            break

    if cached:
        _upsert_usage(api_key_row, accept=True, cache_hit=True, upstream_fetch=False)
        _record_request(api_key_row["id"], "served_from_cache", cache_key, symbol_id=symbol_id, symbols_list=syms,
                        cache_hit=True, upstream_http_status=200,
                        latency_ms=int((time.time() - t0) * 1000),
                        window_size=window_size, resp_type=resp_type)
        return {"data": cached.get("payload_json"), "cached": True, "cache_key": cache_key}

    payload = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key and c.get("tool_name") == tool_name:
            payload = c.get("payload_json")
            break
    if payload is None:
        def _mk(symx):
            return {"symbol": symx, "windowSize": window_size, "type": resp_type}
        payload = _mk(sym) if sym else [_mk(s) for s in syms]

    ttl_ms = int(api_key_row.get("default_cache_ttl_ms", 0))
    if ttl_ms < 0:
        ttl_ms = 0
    fetched_at = now
    expires_at = now + datetime.timedelta(milliseconds=ttl_ms)

    found = None
    for c in cache:
        if isinstance(c, dict) and c.get("cache_key") == cache_key:
            found = c
            break
    if found:
        found["tool_name"] = tool_name
        found["primary_symbol_id"] = symbol_id
        found["symbols"] = syms
        found["interval"] = None
        found["start_time_ms"] = None
        found["end_time_ms"] = None
        found["time_zone"] = None
        found["time_zone_offset_minutes"] = None
        found["from_id"] = None
        found["limit"] = None
        found["window_size"] = window_size
        found["response_type"] = resp_type
        found["payload_json"] = payload
        try:
            found["payload_bytes"] = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
        except Exception:
            found["payload_bytes"] = 0
        found["source"] = "binance_upstream"
        found["status"] = "fresh"
        found["fetched_at"] = _iso(fetched_at)
        found["expires_at"] = _iso(expires_at)
        found["updated_at"] = _iso(now)
    else:
        cache.append({
            "id": _new_id("bmk_cch"),
            "cache_key": cache_key,
            "tool_name": tool_name,
            "primary_symbol_id": symbol_id,
            "symbols": syms,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": None,
            "window_size": window_size,
            "response_type": resp_type,
            "payload_json": payload,
            "payload_bytes": len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) if isinstance(payload, (dict, list)) else 0,
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": _iso(fetched_at),
            "expires_at": _iso(expires_at),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
    _save("market_data_cache.json", cache)

    _upsert_usage(api_key_row, accept=True, cache_hit=False, upstream_fetch=True)
    _record_request(api_key_row["id"], "fetched_upstream", cache_key, symbol_id=symbol_id, symbols_list=syms,
                    cache_hit=False, upstream_http_status=200,
                    latency_ms=int((time.time() - t0) * 1000),
                    window_size=window_size, resp_type=resp_type)
    return {"data": payload, "cached": False, "cache_key": cache_key}

def get_symbols(api_key, status=None, baseAsset=None, quoteAsset=None, symbolPrefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_to_ms(dt):
        if not isinstance(dt, datetime.datetime): return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return int(dt.timestamp() * 1000)

    def _parse_dt(val):
        if val is None: return None
        if isinstance(val, datetime.datetime): 
            return val if val.tzinfo else val.replace(tzinfo=datetime.timezone.utc)
        if isinstance(val, str):
            s = val.strip()
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{int(_now().timestamp()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:12]}"

    def _b64url_json(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _unb64url_json(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    requests = _load("requests.json")
    api_keys = _load("api_keys.json")
    symbols = _load("symbols.json")
    usage = _load("usage_counters.json")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in ("active", "disabled", "delisted"):
        return _err("VALIDATION_ERROR", "Invalid status filter")
    for nm, v in (("baseAsset", baseAsset), ("quoteAsset", quoteAsset), ("symbolPrefix", symbolPrefix)):
