            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(cursor_obj["offset"], int) or cursor_obj["offset"] < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    tool_name = "get_symbols"
    now = _now()

