        "cache_hit": False,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    requests.append(req_row)

    def _finalize_and_save(req_status, error_code=None, error_message=None, rejected=False):
        req_row["status"] = req_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["updated_at"] = _now().isoformat()
