        if key_row:
            # ensure buckets exist; count accepted vs rejected for visibility
            def _bucket_start(dt, kind):
                if kind == "minute":
                    return dt.replace(second=0, microsecond=0)
                return dt.replace(hour=0, minute=0, second=0, microsecond=0)
            for kind in ("minute", "day"):
                bstart = _bucket_start(_now(), kind)
