                        break
                if row is None:
                    row = {
                        "id": _new_id("usage"),
                        "api_key_id": key_row["id"],
                        "bucket_type": kind,
                        "bucket_start": bs_iso,
                        "requests_total": 0,
                        "requests_rejected": 0,
                        "upstream_fetches": 0,
                        "cache_hits": 0,
                        "created_at": _now().isoformat(),
                        "updated_at": _now().isoformat(),
                    }
                    usage.append(row)
                if rejected:
                    row["requests_rejected"] += 1
                else:
                    row["requests_total"] += 1
                row["updated_at"] = _now().isoformat()
            _save("usage_counters.json", usage)

    if not key_row or key_row.get("status") != "active":
        _finalize_and_save("rejected", "API_KEY_INACTIVE", "API key is invalid or inactive", rejected=True)
        return _err("UNAUTHORIZED", "API key is invalid or inactive")

    # Apply filters
    items = symbols
    if status is not None:
        items = [s for s in items if s.get("status") == status]
    if baseAsset is not None:
        items = [s for s in items if s.get("base_asset") == baseAsset]
    if quoteAsset is not None:
        items = [s for s in items if s.get("quote_asset") == quoteAsset]
    if symbolPrefix is not None:
        p = symbolPrefix.lower()
        items = [s for s in items if isinstance(s.get("symbol"), str) and s["symbol"].lower().startswith(p)]

    # Deterministic ordering for paging
    items.sort(key=lambda s: (s.get("symbol") or "", s.get("id") or ""))

    offset = cursor_obj["offset"] if cursor_obj else 0
    total = len(items)
    page = items[offset: offset + limit_n]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _b64url_json({"v": 1, "offset": next_offset}) if has_more else None

    # Served (no cache concept here)
    _finalize_and_save("fetched_upstream", None, None, rejected=False)

    return {
        "data": {
            "items": page,
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_requests(api_key, status=None, tool_name=None, symbol=None, from_created_at_ms=None, to_created_at_ms=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(val):
        if val is None: return None
        if isinstance(val, datetime.datetime):
            return val if val.tzinfo else val.replace(tzinfo=datetime.timezone.utc)
        if isinstance(val, str):
            s = val.strip()
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{int(_now().timestamp()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:12]}"

    def _b64url_json(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _unb64url_json(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Load
    requests_rows = _load("requests.json")
    api_keys = _load("api_keys.json")
    symbols_rows = _load("symbols.json")
    usage = _load("usage_counters.json")

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in ("received", "served_from_cache", "fetched_upstream", "failed", "rejected"):
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if tool_name is not None and not isinstance(tool_name, str):
        return _err("VALIDATION_ERROR", "tool_name must be a string")
    if symbol is not None and not isinstance(symbol, str):
        return _err("VALIDATION_ERROR", "symbol must be a string")
    if from_created_at_ms is not None:
        if not isinstance(from_created_at_ms, int) or from_created_at_ms < 0:
            return _err("VALIDATION_ERROR", "from_created_at_ms must be an integer >= 0")
    if to_created_at_ms is not None:
        if not isinstance(to_created_at_ms, int) or to_created_at_ms < 0:
            return _err("VALIDATION_ERROR", "to_created_at_ms must be an integer >= 0")
    if from_created_at_ms is not None and to_created_at_ms is not None and to_created_at_ms < from_created_at_ms:
        return _err("VALIDATION_ERROR", "to_created_at_ms must be >= from_created_at_ms")
    if limit is None:
        limit_n = 100
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 500:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
        limit_n = limit
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        cursor_obj = _unb64url_json(cursor)
        if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if "before" not in cursor_obj or not isinstance(cursor_obj["before"], str) or not cursor_obj["before"]:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Auth
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key or r.get("name") == api_key or r.get("key_hash") == api_key:
            key_row = r
            break

    # Write audit request for this tool
    now = _now()
    audit_row = {
        "id": _new_id("req"),
        "api_key_id": key_row.get("id") if key_row else "unknown",
        "tool_name": "get_requests",
        "status": "received",
        "symbol_id": None,
        "symbols": None,
        "interval": None,
        "start_time_ms": None,
        "end_time_ms": None,
        "time_zone": None,
        "time_zone_offset_minutes": None,
        "from_id": None,
        "limit": limit_n,
        "window_size": None,
        "response_type": None,
        "cache_key": f"get_requests|status={status or ''}|tool={tool_name or ''}|symbol={symbol or ''}|from={from_created_at_ms or ''}|to={to_created_at_ms or ''}|limit={limit_n}|cursor={(cursor or '')}",
        "cache_hit": False,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    requests_rows.append(audit_row)

    def _finalize(req_status, error_code=None, error_message=None, rejected=False):
        audit_row["status"] = req_status
        audit_row["error_code"] = error_code
        audit_row["error_message"] = error_message
        audit_row["updated_at"] = _now().isoformat()
        audit_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        _save("requests.json", requests_rows)
        if key_row:
            def _bucket_start(dt, kind):
                if kind == "minute":
                    return dt.replace(second=0, microsecond=0)
                return dt.replace(hour=0, minute=0, second=0, microsecond=0)
            for kind in ("minute", "day"):
                bstart = _bucket_start(_now(), kind)
                bs_iso = bstart.isoformat()
                row = None
                for u in usage:
                    if u.get("api_key_id") == key_row["id"] and u.get("bucket_type") == kind and u.get("bucket_start") == bs_iso:
                        row = u
                        break
                if row is None:
                    row = {
                        "id": _new_id("usage"),
                        "api_key_id": key_row["id"],
                        "bucket_type": kind,
                        "bucket_start": bs_iso,
                        "requests_total": 0,
                        "requests_rejected": 0,
                        "upstream_fetches": 0,
                        "cache_hits": 0,
                        "created_at": _now().isoformat(),
                        "updated_at": _now().isoformat(),
                    }
                    usage.append(row)
                if rejected:
                    row["requests_rejected"] += 1
                else:
                    row["requests_total"] += 1
                row["updated_at"] = _now().isoformat()
            _save("usage_counters.json", usage)

    if not key_row or key_row.get("status") != "active":
        _finalize("rejected", "API_KEY_INACTIVE", "API key is invalid or inactive", rejected=True)
        return _err("UNAUTHORIZED", "API key is invalid or inactive")

    # Build symbol lookup for filter
    symbol_to_id = {}
    for s in symbols_rows:
        sym = s.get("symbol")
        if isinstance(sym, str):
            symbol_to_id[sym] = s.get("id")
    filter_symbol_id = None
    if symbol is not None:
        filter_symbol_id = symbol_to_id.get(symbol)
        # For audit listing, if the symbol doesn't exist, just return empty set (filter matches nothing), not an error.

    # Filter rows for this api_key_id
    my_id = key_row["id"]
    items = [r for r in requests_rows if r.get("api_key_id") == my_id and r.get("tool_name") != "get_requests"]
    # Apply filters
    if status is not None:
        items = [r for r in items if r.get("status") == status]
    if tool_name is not None:
        items = [r for r in items if r.get("tool_name") == tool_name]
    if filter_symbol_id is not None:
        items = [r for r in items if r.get("symbol_id") == filter_symbol_id]
    if from_created_at_ms is not None:
        def ok_from(r):
            dt = _parse_dt(r.get("created_at"))
            return dt is not None and int(dt.timestamp()*1000) >= from_created_at_ms
        items = [r for r in items if ok_from(r)]
    if to_created_at_ms is not None:
        def ok_to(r):
            dt = _parse_dt(r.get("created_at"))
            return dt is not None and int(dt.timestamp()*1000) <= to_created_at_ms
        items = [r for r in items if ok_to(r)]

    # Sort newest first (created_at, then id)
    def sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        ts = dt.timestamp() if dt else 0.0
        return (ts, r.get("id") or "")
    items.sort(key=sort_key, reverse=True)

    # Cursor is "before" created_at iso
    if cursor_obj:
        before_iso = cursor_obj["before"]
        before_dt = _parse_dt(before_iso)
        if before_dt is None:
            _finalize("failed", "INVALID_CURSOR", "Cursor could not be parsed", rejected=True)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        def before_filter(r):
            dt = _parse_dt(r.get("created_at"))
            if dt is None: 
                return False
            return dt < before_dt
        items = [r for r in items if before_filter(r)]

    total = len(items)
    page = items[:limit_n]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last_dt = _parse_dt(page[-1].get("created_at"))
        if last_dt is None:
            next_cursor = None
        else:
            next_cursor = _b64url_json({"v": 1, "before": last_dt.isoformat()})

    _finalize("fetched_upstream", None, None, rejected=False)
    return {
        "data": {
            "items": page,
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

