            return dt is not None and int(dt.timestamp()*1000) <= expires_before_ms
        items = [c for c in items if ok_before(c)]

    # Sort newest fetched first
    def sort_key(c):
        dt = _parse_dt(c.get("fetched_at"))
        ts = dt.timestamp() if dt else 0.0
        return (ts, c.get("id") or "")
    items.sort(key=sort_key, reverse=True)

    offset = cursor_obj["offset"] if cursor_obj else 0
    total = len(items)
    page = items[offset: offset + limit_n]

    # Shape response items (omit payload unless requested)
    out = []
    for c in page:
        if include_payload_b:
            out.append(c)
        else:
            cc = dict(c)
            if "payload_json" in cc:
                del cc["payload_json"]
            out.append(cc)

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _b64url_json({"v": 1, "offset": next_offset}) if has_more else None

    _finalize("fetched_upstream", None, None, rejected=False)
    return {
        "data": {
            "items": out,
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def refresh_market_data_cache(api_key, tool_name, symbol=None, symbols=None, interval=None, startTime=None, endTime=None, timeZone=None, timeZoneOffsetMinutes=None, fromId=None, limit=None, windowSize=None, type=None, ttl_ms=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_called = "refresh_market_data_cache"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _cache_key(tool, params):
        h = hashlib.sha256((tool + "|" + _stable_json(params)).encode("utf-8")).hexdigest()
        return f"{tool}:{h}"

    def _find_api_key_row(presented, api_keys_rows):
        # Authenticate by matching provided value to row.id OR row.key_hash (client-visible value in this store).
        for r in api_keys_rows:
            if isinstance(r, dict) and (r.get("id") == presented or r.get("key_hash") == presented):
                return r
        return None

    def _get_or_create_counter(counters, api_key_id, bucket_type, bucket_start_dt, now_iso):
        bs_iso = _iso(bucket_start_dt)
        for r in counters:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                return r
        row = {
            "id": _new_id("bmk_use"),
            "api_key_id": api_key_id,
            "bucket_type": bucket_type,
            "bucket_start": bs_iso,
            "requests_total": 0,
            "requests_rejected": 0,
            "upstream_fetches": 0,
            "cache_hits": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    def _record_request(req_rows, api_key_id, tool_name_target, status, cache_key_s, cache_hit, symbol_id=None, symbols_list=None,
                        interval=None, start_time_ms=None, end_time_ms=None, time_zone=None, time_zone_offset_minutes=None,
                        from_id=None, limit=None, window_size=None, response_type=None,
                        error_code=None, error_message=None, upstream_http_status=None, latency_ms=None):
        now = _now()
        now_iso = _iso(now)
        row = {
            "id": _new_id("bmk_req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name_target,
            "status": status,
            "symbol_id": symbol_id,
            "symbols": symbols_list,
            "interval": interval,
            "start_time_ms": start_time_ms,
            "end_time_ms": end_time_ms,
            "time_zone": time_zone,
            "time_zone_offset_minutes": time_zone_offset_minutes,
            "from_id": from_id,
            "limit": limit,
            "window_size": window_size,
            "response_type": response_type,
            "cache_key": cache_key_s,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        req_rows.append(row)
        return row

    # Load store
    api_keys = _load("api_keys.json")
    sym_rows = _load("symbols.json")
    req_rows = _load("requests.json")
    cache_rows = _load("market_data_cache.json")
    usage = _load("usage_counters.json")

    now = _now()
    now_iso = _iso(now)

    # Validate required inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(tool_name, str) or not tool_name.strip():
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string")

    allowed_tools = {
        "get_order_book", "get_recent_trades", "get_historical_trades", "get_aggregate_trades",
        "get_klines", "get_ui_klines", "get_24hr_ticker", "get_trading_day_ticker", "get_price",
        "get_book_ticker", "get_rolling_window_ticker"
    }
    if tool_name not in allowed_tools:
        return _err("VALIDATION_ERROR", "tool_name is not supported")

    # Authenticate explicit credential
    api_key_row = _find_api_key_row(api_key.strip(), api_keys)
    api_key_id = api_key_row.get("id") if api_key_row else None
    if not api_key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if api_key_row.get("status") != "active":
        # Write rejected request row for audit per business rule.
        ck = _cache_key(tool_name, {"symbol": symbol, "symbols": symbols})
        _record_request(req_rows, api_key_id, tool_name, "rejected", ck, False, error_code="API_KEY_INACTIVE", error_message="API key is not active", latency_ms=int((time.time() - t0) * 1000))
        minute = _bucket_start(now, "minute")
        day = _bucket_start(now, "day")
        cmin = _get_or_create_counter(usage, api_key_id, "minute", minute, now_iso)
        cday = _get_or_create_counter(usage, api_key_id, "day", day, now_iso)
        cmin["requests_rejected"] = int(cmin.get("requests_rejected") or 0) + 1
        cday["requests_rejected"] = int(cday.get("requests_rejected") or 0) + 1
        cmin["updated_at"] = now_iso
        cday["updated_at"] = now_iso
        _save("requests.json", req_rows)
        _save("usage_counters.json", usage)
        return _err("UNAUTHORIZED", "API key is not active", error_code="API_KEY_INACTIVE")

    # Normalize / validate symbols vs symbol.
    # IMPORTANT RELAXATION: if both are provided but symbols isn't a valid list-of-strings, ignore symbols and proceed with symbol.
    sym_val = None
    syms_val = None

    if symbol is not None and not (isinstance(symbol, str) and symbol.strip()):
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if symbols is not None and not isinstance(symbols, list):
        # invalid; if symbol present, ignore symbols, else error
        if symbol is None:
            return _err("VALIDATION_ERROR", "symbols must be a non-empty array of strings")
        symbols = None

    if symbol is not None and symbols is not None:
        # both are present and symbols is list -> strict mutual exclusivity
        return _err("VALIDATION_ERROR", "Provide either 'symbol' or 'symbols', not both.")

    if symbols is not None:
        cleaned = []
        for s in symbols:
            if not isinstance(s, str) or not s.strip():
                return _err("VALIDATION_ERROR", "symbols must be a non-empty array of strings")
            cleaned.append(s.strip().upper())
        if len(cleaned) == 0:
            return _err("VALIDATION_ERROR", "symbols must be a non-empty array of strings")
        if len(set(cleaned)) != len(cleaned):
            return _err("VALIDATION_ERROR", "symbols[] must not contain duplicates", error_code="DUPLICATE_SYMBOLS")
        if len(cleaned) > int(api_key_row.get("max_symbols_per_request") or 1):
            return _err("VALIDATION_ERROR", "symbols[] exceeds max_symbols_per_request")
        syms_val = cleaned
    elif symbol is not None:
        sym_val = symbol.strip().upper()

    # Tool-specific validations
    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
    if tool_name in ("get_klines", "get_ui_klines"):
        if interval is not None and interval not in allowed_intervals:
            return _err("VALIDATION_ERROR", "interval must be one of the allowed values")
        if timeZone is None:
            time_zone = "UTC"
        else:
            if not isinstance(timeZone, str) or not timeZone.strip():
                return _err("VALIDATION_ERROR", "timeZone must be a non-empty string")
            time_zone = timeZone.strip()
    else:
        time_zone = None

    if tool_name == "get_trading_day_ticker":
        tz_off = 0 if timeZoneOffsetMinutes is None else timeZoneOffsetMinutes
        if not isinstance(tz_off, int):
            return _err("VALIDATION_ERROR", "timeZoneOffsetMinutes must be an integer")
        if tz_off < -840 or tz_off > 840:
            return _err("VALIDATION_ERROR", "timeZoneOffsetMinutes must be between -840 and 840")
    else:
        tz_off = None

    if tool_name in ("get_trading_day_ticker", "get_rolling_window_ticker"):
        resp_type = "FULL" if type is None else type
        if resp_type not in ("FULL", "MINI"):
            return _err("VALIDATION_ERROR", "type must be FULL or MINI")
    else:
        resp_type = None

    if tool_name == "get_rolling_window_ticker":
        if windowSize is None:
            window_size = "1d"
        else:
            if not isinstance(windowSize, str) or not windowSize.strip():
                window_size = "1d"
            else:
                window_size = windowSize.strip()
    else:
        window_size = None

    # Numeric validations
    if fromId is not None:
        if not isinstance(fromId, int) or fromId < 0:
            return _err("VALIDATION_ERROR", "fromId must be an integer >= 0")
    if startTime is not None:
        if not isinstance(startTime, int) or startTime < 0:
            return _err("VALIDATION_ERROR", "startTime must be an integer >= 0")
    if endTime is not None:
        if not isinstance(endTime, int) or endTime < 0:
            return _err("VALIDATION_ERROR", "endTime must be an integer >= 0")
    if startTime is not None and endTime is not None and endTime < startTime:
        return _err("VALIDATION_ERROR", "endTime must be >= startTime", error_code="INVALID_TIME_RANGE")

    # Limit per tool
    if tool_name == "get_order_book":
        if limit is None:
            lim = None
        else:
            if not isinstance(limit, int) or limit < 1 or limit > 5000:
                return _err("VALIDATION_ERROR", "limit must be between 1 and 5000", error_code="INVALID_LIMIT")
            lim = limit
    elif tool_name in ("get_recent_trades", "get_historical_trades", "get_aggregate_trades", "get_klines", "get_ui_klines"):
        if limit is None:
            lim = 500  # service default for these endpoints
        else:
            if not isinstance(limit, int) or limit < 1 or limit > 1000:
                return _err("VALIDATION_ERROR", "limit must be between 1 and 1000", error_code="INVALID_LIMIT")
            lim = limit
    else:
        lim = None

    # Validate symbols exist and active where applicable
    sym_by_symbol = {r.get("symbol"): r for r in sym_rows if isinstance(r, dict)}
    def _ensure_active(sym):
        r = sym_by_symbol.get(sym)
        if not r:
            return None, "unknown"
        if r.get("status") != "active":
            return None, "inactive"
        return r, None

    primary_symbol_id = None
    symbols_list = None
    if sym_val is not None:
        r, why = _ensure_active(sym_val)
        if why == "unknown":
            return _err("NOT_FOUND", f"Unknown symbol: {sym_val}")
        if why == "inactive":
            return _err("VALIDATION_ERROR", f"Unknown symbol: {sym_val}", error_code="UNKNOWN_SYMBOL")
        primary_symbol_id = r["id"]
    if syms_val is not None:
        for s in syms_val:
            r, why = _ensure_active(s)
            if why == "unknown":
                return _err("NOT_FOUND", f"Unknown symbol: {s}")
            if why == "inactive":
                return _err("VALIDATION_ERROR", f"Unknown symbol: {s}", error_code="UNKNOWN_SYMBOL")
        symbols_list = syms_val

    # Quota enforcement for accepted refresh: increment buckets and reject if would exceed
    minute = _bucket_start(now, "minute")
    day = _bucket_start(now, "day")
    cmin = _get_or_create_counter(usage, api_key_id, "minute", minute, now_iso)
    cday = _get_or_create_counter(usage, api_key_id, "day", day, now_iso)

    rpm_limit = int(api_key_row.get("rpm_limit") or 1)
    day_limit = int(api_key_row.get("daily_request_limit") or 1)

    # Cache key includes normalized params for the target tool
    params = {}
    if sym_val is not None:
        params["symbol"] = sym_val
    if symbols_list is not None:
        params["symbols"] = sorted(symbols_list)
    if tool_name in ("get_klines", "get_ui_klines"):
        params["interval"] = interval
        params["startTime"] = startTime
        params["endTime"] = endTime
        params["timeZone"] = time_zone
        params["limit"] = lim
    if tool_name in ("get_recent_trades", "get_historical_trades", "get_aggregate_trades"):
        params["fromId"] = fromId
        params["limit"] = lim
        if tool_name == "get_aggregate_trades":
            params["startTime"] = startTime
            params["endTime"] = endTime
    if tool_name == "get_order_book":
        params["limit"] = lim
    if tool_name == "get_trading_day_ticker":
        params["type"] = resp_type
        params["timeZoneOffsetMinutes"] = tz_off
    if tool_name == "get_rolling_window_ticker":
        params["type"] = resp_type
        params["windowSize"] = window_size

    ck = _cache_key(tool_name, params)

    if int(cmin.get("requests_total") or 0) + 1 > rpm_limit or int(cday.get("requests_total") or 0) + 1 > day_limit:
        _record_request(req_rows, api_key_id, tool_name, "rejected", ck, False, symbol_id=primary_symbol_id, symbols_list=symbols_list,
                        interval=interval if tool_name in ("get_klines","get_ui_klines") else None,
                        start_time_ms=startTime, end_time_ms=endTime, time_zone=time_zone, time_zone_offset_minutes=tz_off,
                        from_id=fromId, limit=lim, window_size=window_size, response_type=resp_type,
                        error_code="RATE_LIMITED", error_message="RPM or daily quota exceeded for API key", latency_ms=int((time.time() - t0) * 1000))
        cmin["requests_rejected"] = int(cmin.get("requests_rejected") or 0) + 1
        cday["requests_rejected"] = int(cday.get("requests_rejected") or 0) + 1
        cmin["updated_at"] = now_iso
        cday["updated_at"] = now_iso
        _save("requests.json", req_rows)
        _save("usage_counters.json", usage)
        return _err("QUOTA_EXCEEDED", "Quota would be exceeded for API key", error_code="RATE_LIMITED")

    cmin["requests_total"] = int(cmin.get("requests_total") or 0) + 1
    cday["requests_total"] = int(cday.get("requests_total") or 0) + 1
    cmin["updated_at"] = now_iso
    cday["updated_at"] = now_iso

    # Upstream fetch simulation: create minimal payload for the requested tool
    def _payload_for_tool():
        # keep consistent with read tools shapes above where possible
        if tool_name == "get_price":
            def _mk(sym):
                h = int(hashlib.sha256((sym + now_iso).encode("utf-8")).hexdigest()[:12], 16)
                last = (h % 1000000) / 100.0 + 1.0
                return {"symbol": sym, "price": f"{last:.8f}"}
            if sym_val is not None:
                return _mk(sym_val)
            return [_mk(s) for s in symbols_list]
        if tool_name == "get_book_ticker":
            def _mk(sym):
                h = int(hashlib.sha256((sym + now_iso).encode("utf-8")).hexdigest()[:12], 16)
                mid = (h % 1000000) / 100.0 + 1.0
                return {"symbol": sym, "bidPrice": f"{max(mid-0.01,0):.8f}", "bidQty": "0.00000000", "askPrice": f"{mid+0.01:.8f}", "askQty": "0.00000000"}
            if sym_val is not None:
                return _mk(sym_val)
            return [_mk(s) for s in symbols_list]
        # fallback generic
        base = {"tool": tool_name, "refreshedAt": int(now.timestamp() * 1000)}
        if sym_val is not None:
            base["symbol"] = sym_val
        if symbols_list is not None:
            base["symbols"] = symbols_list
        if interval is not None:
            base["interval"] = interval
        if startTime is not None:
            base["startTime"] = startTime
        if endTime is not None:
            base["endTime"] = endTime
        if time_zone is not None:
            base["timeZone"] = time_zone
        if tz_off is not None:
            base["timeZoneOffsetMinutes"] = tz_off
        if fromId is not None:
            base["fromId"] = fromId
        if lim is not None:
            base["limit"] = lim
        if window_size is not None:
            base["windowSize"] = window_size
        if resp_type is not None:
            base["type"] = resp_type
        return base

    payload = _payload_for_tool()

    # TTL override
    if ttl_ms is None:
        ttl_val = int(api_key_row.get("default_cache_ttl_ms") or 0)
    else:
        if not isinstance(ttl_ms, int) or ttl_ms < 0:
            return _err("VALIDATION_ERROR", "ttl_ms must be an integer >= 0")
        ttl_val = ttl_ms
    if ttl_val < 0:
        ttl_val = 0

    expires_at = now + datetime.timedelta(milliseconds=ttl_val)
    payload_bytes = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))

    # Upsert cache by cache_key
    entry = None
    for r in cache_rows:
        if isinstance(r, dict) and r.get("cache_key") == ck:
            entry = r
            break

    if entry:
        entry["tool_name"] = tool_name
        entry["primary_symbol_id"] = primary_symbol_id
        entry["symbols"] = sorted(symbols_list) if symbols_list is not None else None
        entry["interval"] = interval if tool_name in ("get_klines","get_ui_klines") else None
        entry["start_time_ms"] = startTime
        entry["end_time_ms"] = endTime
        entry["time_zone"] = time_zone
        entry["time_zone_offset_minutes"] = tz_off
        entry["from_id"] = fromId
        entry["limit"] = lim
        entry["window_size"] = window_size
        entry["response_type"] = resp_type
        entry["payload_json"] = payload
        entry["payload_bytes"] = int(payload_bytes)
        entry["source"] = "binance_upstream"
        entry["status"] = "fresh"
        entry["fetched_at"] = now_iso
        entry["expires_at"] = _iso(expires_at)
        entry["updated_at"] = now_iso
    else:
        cache_rows.append({
            "id": _new_id("bmk_cch"),
            "cache_key": ck,
            "tool_name": tool_name,
            "primary_symbol_id": primary_symbol_id,
            "symbols": sorted(symbols_list) if symbols_list is not None else None,
            "interval": interval if tool_name in ("get_klines","get_ui_klines") else None,
            "start_time_ms": startTime,
            "end_time_ms": endTime,
            "time_zone": time_zone,
            "time_zone_offset_minutes": tz_off,
            "from_id": fromId,
            "limit": lim,
            "window_size": window_size,
            "response_type": resp_type,
            "payload_json": payload,
            "payload_bytes": int(payload_bytes),
            "source": "binance_upstream",
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": _iso(expires_at),
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    _record_request(req_rows, api_key_id, tool_name, "fetched_upstream", ck, False, symbol_id=primary_symbol_id, symbols_list=symbols_list,
                    interval=interval if tool_name in ("get_klines","get_ui_klines") else None,
                    start_time_ms=startTime, end_time_ms=endTime, time_zone=time_zone, time_zone_offset_minutes=tz_off,
                    from_id=fromId, limit=lim, window_size=window_size, response_type=resp_type,
                    upstream_http_status=200, latency_ms=int((time.time() - t0) * 1000))

    cmin["upstream_fetches"] = int(cmin.get("upstream_fetches") or 0) + 1
    cday["upstream_fetches"] = int(cday.get("upstream_fetches") or 0) + 1

    _save("market_data_cache.json", cache_rows)
    _save("requests.json", req_rows)
    _save("usage_counters.json", usage)

    return {
        "cache_key": ck,
        "tool_name": tool_name,
        "expires_at": _iso(expires_at),
        "payload": payload,
        "served_from_cache": False
    }

def purge_market_data_cache(api_key, cache_key=None, tool_name=None, symbol=None, symbols=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_enum = {
        "get_order_book", "get_recent_trades", "get_historical_trades", "get_aggregate_trades",
        "get_klines", "get_ui_klines", "get_avg_price", "get_24hr_ticker", "get_trading_day_ticker",
        "get_price", "get_book_ticker", "get_rolling_window_ticker"
    }

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _select_api_key_row(api_key_value):
        # Authenticate by matching caller-provided value to api_keys.id OR api_keys.name (client-visible).
        keys = _load("api_keys.json") or []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if api_key_value == k.get("id") or api_key_value == k.get("name"):
                return k
        return None

    def _record_request(api_key_id, status, cache_key_val, error_code=None, error_message=None, latency_ms=None):
        reqs = _load("requests.json") or []
        now = _now()
        reqs.append({
            "id": _new_id("bmk_req"),
            "api_key_id": api_key_id,
            "tool_name": "get_book_ticker",  # closest in enum; purge is not in enum, so we log under book_ticker policy
            "status": status,
            "symbol_id": None,
            "symbols": None,
            "interval": None,
            "start_time_ms": None,
            "end_time_ms": None,
            "time_zone": None,
            "time_zone_offset_minutes": None,
            "from_id": None,
            "limit": None,
            "window_size": None,
            "response_type": None,
            "cache_key": cache_key_val or "purge_market_data_cache|n/a",
            "cache_hit": False,
            "upstream_http_status": None,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("requests.json", reqs)

    def _upsert_usage(api_key_row, accept):
        usage = _load("usage_counters.json") or []
        now = _now()
        api_key_id = api_key_row["id"]

        def _find_or_create(bucket_type):
            bstart = _bucket_start(now, bucket_type)
            bstart_iso = _iso(bstart)
            for r in usage:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bstart_iso:
                    return r
            r = {
                "id": _new_id("bmk_use"),
                "api_key_id": api_key_id,
                "bucket_type": bucket_type,
                "bucket_start": bstart_iso,
                "requests_total": 0,
                "requests_rejected": 0,
                "upstream_fetches": 0,
                "cache_hits": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            usage.append(r)
            return r

        minute = _find_or_create("minute")
        day = _find_or_create("day")

        if accept:
            if minute["requests_total"] + 1 > int(api_key_row.get("rpm_limit", 1)):
                minute["requests_rejected"] += 1
                day["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "RATE_LIMITED", "RPM quota exceeded for API key"
            if day["requests_total"] + 1 > int(api_key_row.get("daily_request_limit", 1)):
                minute["requests_rejected"] += 1
                day["requests_rejected"] += 1
                minute["updated_at"] = _iso(now)
                day["updated_at"] = _iso(now)
                _save("usage_counters.json", usage)
                return False, "QUOTA_EXCEEDED", "Daily request quota exceeded for API key"
            minute["requests_total"] += 1
            day["requests_total"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None
        else:
            minute["requests_rejected"] += 1
            day["requests_rejected"] += 1
            minute["updated_at"] = _iso(now)
            day["updated_at"] = _iso(now)
            _save("usage_counters.json", usage)
            return True, None, None

    # --- validate inputs ---
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string (tool schema)")

    if cache_key is not None and (not isinstance(cache_key, str) or not cache_key.strip()):
        return _err("VALIDATION_ERROR", "cache_key must be a non-empty string when provided (tool schema)")

    if tool_name is not None:
        if not isinstance(tool_name, str):
            return _err("VALIDATION_ERROR", "tool_name must be a string (tool schema)")
        if tool_name not in tool_enum:
            return _err("VALIDATION_ERROR", "tool_name must be one of the allowed tool names (tool schema)")

    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided (tool schema)")

    # Relaxed symbols validation (audit): accept malformed symbols by ignoring them; only validate if it is a proper string list.
    symbols_list = None
    if symbols is not None:
        if isinstance(symbols, list) and all(isinstance(x, str) for x in symbols) and len(symbols) > 0:
            symbols_list = [s.strip().upper() for s in symbols if isinstance(s, str) and s.strip()]
            if len(symbols_list) == 0:
                symbols_list = None
        else:
            symbols_list = None

    if not cache_key and not tool_name and not symbol and not symbols_list:
        return _err("VALIDATION_ERROR", "Provide cache_key or at least one purge filter (tool_name/symbol/symbols) (business rule)")

    # --- auth ---
    key_row = _select_api_key_row(api_key)
    if not key_row or key_row.get("status") != "active":
        # write rejected request
        _record_request(api_key_id=key_row["id"] if key_row else "unknown",
                        status="rejected",
                        cache_key_val=cache_key,
                        error_code="API_KEY_INACTIVE",
                        error_message="API key is not active",
                        latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is invalid or inactive", error_code="API_KEY_INACTIVE")

    # quota (counts purge operations too)
    ok, q_code, q_msg = _upsert_usage(key_row, accept=True)
    if not ok:
        _record_request(api_key_id=key_row["id"], status="rejected", cache_key_val=cache_key,
                        error_code=q_code, error_message=q_msg, latency_ms=int((time.time() - t0) * 1000))
        return _err("RATE_LIMIT" if q_code == "RATE_LIMITED" else "QUOTA_EXCEEDED", q_msg, error_code=q_code)

    # --- perform mutation ---
    cache = _load("market_data_cache.json") or []
    now = _now()
    affected = 0

    def _matches(entry):
        if not isinstance(entry, dict):
            return False
        if cache_key and entry.get("cache_key") != cache_key:
            return False
        if tool_name and entry.get("tool_name") != tool_name:
            return False
        if symbol:
            # symbol filter applies to primary symbol (match by symbol string requires lookup via symbols table)
            # Prefer matching on stored primary_symbol_id when possible.
            sym_rows = _load("symbols.json") or []
            target_sym = symbol.strip().upper()
            target_id = None
            for r in sym_rows:
                if isinstance(r, dict) and isinstance(r.get("symbol"), str) and r["symbol"].upper() == target_sym:
                    target_id = r.get("id")
                    break
            if target_id:
                if entry.get("primary_symbol_id") != target_id:
                    return False
            else:
                return False
        if symbols_list:
            entry_syms = entry.get("symbols")
            if not isinstance(entry_syms, list):
                return False
            entry_set = set([s.upper() for s in entry_syms if isinstance(s, str)])
            if not any(s in entry_set for s in symbols_list):
                return False
        return True

    for e in cache:
        if not _matches(e):
            continue
        if e.get("status") == "expired":
            continue  # idempotent
        # lifecycle transition fresh/stale -> expired
        e["status"] = "expired"
        e["updated_at"] = _iso(now)
        # ensure constraint: status='expired' implies expires_at <= updated_at
        e["expires_at"] = _iso(now)
        affected += 1

    if affected == 0:
        _record_request(api_key_id=key_row["id"], status="failed", cache_key_val=cache_key,
                        error_code="NOT_FOUND", error_message="No matching cache entries to purge",
                        latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "No matching cache entries found to purge")

    _save("market_data_cache.json", cache)
    _record_request(api_key_id=key_row["id"], status="fetched_upstream", cache_key_val=cache_key,
                    error_code=None, error_message=None,
                    latency_ms=int((time.time() - t0) * 1000))
    return {"data": {"affected": affected}}

def get_whoami(api_key, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0429000" if __import__("os").path.isdir("./environment_mix/0429000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _bucket_start(dt, bucket_type):
        dt = dt.astimezone(datetime.timezone.utc)
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        if bucket_type == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return None

    def _get_counter(counters, api_key_id, bucket_type, bucket_start_dt):
        bucket_start_iso = _iso(bucket_start_dt)
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bucket_start_iso:
                return r
        return None

    def _find_api_key_row(api_key_presented, api_keys_rows):
        for r in api_keys_rows:
            if r.get("id") == api_key_presented or r.get("key_hash") == api_key_presented:
                return r
        return None

    started = time.time()
    now = _now_utc()

    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")

    api_keys = _load("api_keys.json")
    keyrow = _find_api_key_row(api_key.strip(), api_keys)
    if not keyrow:
        return _err("UNAUTHORIZED", "Invalid API key.")

    api_key_id = keyrow.get("id")

    # Log request (read included). Schema enum for requests.tool_name doesn't include get_whoami; still record.
    requests = _load("requests.json")
    req_id = "req_" + uuid.uuid4().hex
    created_iso = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "get_whoami",
        "status": "received",
        "symbol_id": None,
        "symbols": None,
        "interval": None,
        "start_time_ms": None,
        "end_time_ms": None,
        "time_zone": None,
        "time_zone_offset_minutes": None,
        "from_id": None,
        "limit": None,
        "window_size": None,
        "response_type": None,
        "cache_key": "whoami",
        "cache_hit": False,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "created_at": created_iso,
        "updated_at": created_iso,
    }

    counters = _load("usage_counters.json")
    minute_row = _get_counter(counters, api_key_id, "minute", _bucket_start(now, "minute"))
    day_row = _get_counter(counters, api_key_id, "day", _bucket_start(now, "day"))

    # This endpoint returns status even if suspended/revoked; do not reject unless invalid/missing key.
    req_row["status"] = "served_from_cache"
    req_row["cache_hit"] = True
    req_row["updated_at"] = _iso(_now_utc())
    req_row["latency_ms"] = max(0, int((time.time() - started) * 1000))
    requests.append(req_row)
    _save("requests.json", requests)

    minute_usage = {
        "bucket_start": _iso(_bucket_start(now, "minute")),
        "requests_total": int(minute_row.get("requests_total", 0)) if isinstance(minute_row, dict) else 0,
        "requests_rejected": int(minute_row.get("requests_rejected", 0)) if isinstance(minute_row, dict) else 0,
        "upstream_fetches": int(minute_row.get("upstream_fetches", 0)) if isinstance(minute_row, dict) else 0,
        "cache_hits": int(minute_row.get("cache_hits", 0)) if isinstance(minute_row, dict) else 0,
    }
    day_usage = {
        "bucket_start": _iso(_bucket_start(now, "day")),
        "requests_total": int(day_row.get("requests_total", 0)) if isinstance(day_row, dict) else 0,
        "requests_rejected": int(day_row.get("requests_rejected", 0)) if isinstance(day_row, dict) else 0,
        "upstream_fetches": int(day_row.get("upstream_fetches", 0)) if isinstance(day_row, dict) else 0,
        "cache_hits": int(day_row.get("cache_hits", 0)) if isinstance(day_row, dict) else 0,
    }

    return {
        "api_key": {
            "id": keyrow.get("id"),
            "name": keyrow.get("name"),
            "status": keyrow.get("status"),
            "default_cache_ttl_ms": keyrow.get("default_cache_ttl_ms"),
            "rpm_limit": keyrow.get("rpm_limit"),
            "daily_request_limit": keyrow.get("daily_request_limit"),
            "max_symbols_per_request": keyrow.get("max_symbols_per_request"),
            "created_at": keyrow.get("created_at"),
            "updated_at": keyrow.get("updated_at"),
            "revoked_at": keyrow.get("revoked_at"),
        },
        "usage": {
            "minute": minute_usage,
            "day": day_usage,
            "as_of": _iso(now),
        }
    }
